from collections import deque, Counter

class FirstUnique:
    def __init__(self, nums: list[int]):
        self.counts = Counter(nums)
        self.q = deque(nums)

    def showFirstUnique(self) -> int:
        while self.q and self.counts[self.q[0]] > 1:
            self.q.popleft()
        return self.q[0] if self.q else -1

    def add(self, value: int) -> None:
        self.counts[value] += 1
        self.q.append(value)

class FirstUnique {
    unordered_map<int, int> counts;
    queue<int> q;
public:
    FirstUnique(vector<int>& nums) {
        for (int x : nums) {
            counts[x]++;
            q.push(x);
        }
    }

    int showFirstUnique() {
        while (!q.empty() && counts[q.front()] > 1) {
            q.pop();
        }
        return q.empty() ? -1 : q.front();
    }

    void add(int value) {
        counts[value]++;
        q.push(value);
    }
};

class FirstUnique {
    private Map<Integer, Integer> counts = new HashMap<>();
    private Queue<Integer> q = new LinkedList<>();

    public FirstUnique(int[] nums) {
        for (int x : nums) {
            counts.put(x, counts.getOrDefault(x, 0) + 1);
            q.offer(x);
        }
    }

    public int showFirstUnique() {
        while (!q.isEmpty() && counts.get(q.peek()) > 1) {
            q.poll();
        }
        return q.isEmpty() ? -1 : q.peek();
    }

    public void add(int value) {
        counts.put(value, counts.getOrDefault(value, 0) + 1);
        q.offer(value);
    }
}

var FirstUnique = function(nums) {
    this.counts = new Map();
    this.q = [];
    this.head = 0;
    for (const x of nums) {
        this.add(x);
    }
};

FirstUnique.prototype.showFirstUnique = function() {
    while (this.head < this.q.length && this.counts.get(this.q[this.head]) > 1) {
        this.head++;
    }
    return this.head < this.q.length ? this.q[this.head] : -1;
};

FirstUnique.prototype.add = function(value) {
    this.counts.set(value, (this.counts.get(value) || 0) + 1);
    this.q.push(value);
};
